      hu: "Egy kisebb, kúp alakú hegy Ellában, amely a szent Ádám-csúcshoz való hasonlóságáról kapta a nevét.",
      ro: "Un munte mai mic, de formă conică în Ella, numit după asemănarea sa cu Vârful lui Adam.",
      en: "A smaller, cone-shaped mountain in Ella named for its similarity to the sacred Adam's Peak.",
      es: "Una montaña más pequeña y cónica en Ella, llamada así por su parecido con el sagrado Pico de Adán.",
